using System.Text.RegularExpressions; using InovaGed.Environment.Doctor.Quality;
namespace InovaGed.Environment.Doctor.Checks;
public sealed class IconQualityCheck:IQualityCheck { public string Name=>"Ícones"; public Task<IReadOnlyList<QualityFinding>> RunAsync(QualityContext c,CancellationToken ct){var registry=File.ReadAllText(Path.Combine(c.Root,"InovaGed.Web/Services/AtlasIconRegistry.cs")); var helper=File.ReadAllText(Path.Combine(c.Root,"InovaGed.Web/TagHelpers/AtlasIconTagHelper.cs")); var known=new HashSet<string>(Regex.Matches(registry+helper,"[\"']([a-z][a-z0-9-]+)[\"']").Select(m=>m.Groups[1].Value),StringComparer.OrdinalIgnoreCase);var r=new List<QualityFinding>(); foreach(var f in Directory.EnumerateFiles(Path.Combine(c.Root,"InovaGed.Web/Views"),"*.cshtml",SearchOption.AllDirectories)) foreach(Match m in Regex.Matches(File.ReadAllText(f), "<(?:atlas-icon|app-icon)\\b[^>]*\\bname\\s*=\\s*[\"']([^\"']+)[\"']", RegexOptions.IgnoreCase)) if(!m.Groups[1].Value.StartsWith("@")&&!known.Contains(m.Groups[1].Value))r.Add(new(Name,QualityStatus.Warning,$"Ícone sem alias: {m.Groups[1].Value}","Fallback será renderizado.","Adicionar alias ao AtlasIconTagHelper/AtlasIconRegistry.",Resource:Path.GetRelativePath(c.Root,f))); string[] aliases=["archive","tag","bookmark","alarm","plus-lg","plus","eye","bi-people","bi-person-lock","bi-building","bi-person-badge","settings","health","check","print","box","document","search","qr","scanner","history","users","building"];foreach(var a in aliases)if(!known.Contains(a))r.Add(new(Name,QualityStatus.Warning,$"Alias obrigatório não catalogado: {a}","Pode haver fallback.",$"Mapear o alias '{a}' no catálogo Atlas."));if(r.Count==0)r.Add(new(Name,QualityStatus.Pass,"Ícones e aliases obrigatórios estão catalogados."));return Task.FromResult<IReadOnlyList<QualityFinding>>(r);}}
